// Get the output from the previous node
const item = $input.first();
const outputString = item.json.output;

// Remove the ```json and ``` markdown wrapper if present
let cleanedString = outputString.trim();

// Remove markdown code fences more aggressively
cleanedString = cleanedString
  .replace(/^```json\s*/i, '')  // Remove opening ```json
  .replace(/^```\s*/i, '')       // Remove opening ```
  .replace(/```\s*$/i, '')       // Remove closing ```
  .trim();

// If the string doesn't end with ], try to close it properly
if (!cleanedString.endsWith(']')) {
  // Count opening and closing brackets to determine what's missing
  const openBrackets = (cleanedString.match(/\[/g) || []).length;
  const closeBrackets = (cleanedString.match(/\]/g) || []).length;
  const openBraces = (cleanedString.match(/\{/g) || []).length;
  const closeBraces = (cleanedString.match(/\}/g) || []).length;

  // Add missing closing characters
  for (let i = 0; i < (openBraces - closeBraces); i++) {
    cleanedString += '\n  }';
  }
  for (let i = 0; i < (openBrackets - closeBrackets); i++) {
    cleanedString += '\n]';
  }
}

// Parse the JSON string
let parsedData;
try {
  parsedData = JSON.parse(cleanedString);
} catch (error) {
  // If parsing still fails, try to extract valid JSON objects
  const jsonObjects = [];
  const regex = /\{[^{}]*(?:\{[^{}]*\}[^{}]*)*\}/g;
  let match;

  while ((match = regex.exec(outputString)) !== null) {
    try {
      const obj = JSON.parse(match[0]);
      if (obj.question) { // Only include if it has a question field
        jsonObjects.push(obj);
      }
    } catch (e) {
      // Skip invalid objects
    }
  }

  if (jsonObjects.length > 0) {
    parsedData = jsonObjects;
  } else {
    throw new Error('Failed to parse JSON: ' + error.message + '\n\nReceived: ' + cleanedString.substring(0, 500));
  }
}

// If parsedData is an array, map each item to the output format
if (Array.isArray(parsedData)) {
  return parsedData.map(record => ({
    json: {
      topic: record.topic || '',
      question: record.question || '',
      answer: record.answer || '',
      approach: record.approach || '',
      question_type: record.question_type || 'DES',  // NEW FIELD
      correct_answer: record.correct_answer || '',   // NEW FIELD
      subject: record.subject || '',                 // NEW FIELD
      language: record.language || 'English',        // NEW FIELD
      time_duration: record.time_duration || '',
      marks: record.marks || '',
      difficulty: record.difficulty || '',
      knowledge_type: record.knowledge_type || '',
      date_extracted: record.date_extracted || '',
      for_flashcard: record.for_flashcard || ''
    }
  }));
} else {
  // If it's a single object, return it as one item
  return {
    json: {
      topic: parsedData.topic || '',
      question: parsedData.question || '',
      answer: parsedData.answer || '',
      approach: parsedData.approach || '',
      question_type: parsedData.question_type || 'DES',  // NEW FIELD
      correct_answer: parsedData.correct_answer || '',   // NEW FIELD
      subject: parsedData.subject || '',                 // NEW FIELD
      language: parsedData.language || 'English',        // NEW FIELD
      time_duration: parsedData.time_duration || '',
      marks: parsedData.marks || '',
      difficulty: parsedData.difficulty || '',
      knowledge_type: parsedData.knowledge_type || '',
      date_extracted: parsedData.date_extracted || '',
      for_flashcard: parsedData.for_flashcard || ''
    }
  };
}

// Access binary data from the first input item
const item = $input.first();
const bin = item.binary?.Upload_File_for_extracting_Topics;

let filename = null;
let extension = null;
let fileTypeFlag = "OTHER";

if (bin && bin.fileName) {
  filename = bin.fileName;
  const parts = filename.split(".");
  extension = parts.length > 1 ? parts.pop().toLowerCase() : null;
  if (["xlsx", "xls"].includes(extension)) {
    fileTypeFlag = "EXCEL";
  }
}

// RETURN both JSON + the original binary file
return {
  json: {
    filename,
    fileExtension: extension,
    fileTypeFlag
  },
  binary: {
    Upload_File_for_extracting_Topics: bin
  }
};

// The merge node gives an array of items
const itemsArray = items.map(i => i.json);

// First element contains the Q/A extracted text
const first = itemsArray[0];

// Extract text safely
let data = null;
try {
  data = first.content.parts[0].text;
} catch (e) {
  data = "";
}

// Remaining items are topics
const topics = itemsArray.slice(1).map(t => ({
  chapter_name: t.chapter_name,
  name: t.name
}));

return [
  {
    json: {
      data,
      topics
    }
  }
];
